using System.Collections.Generic;public class Solution{public int Calculate(string s){var st=new Stack<int>();int n=0;char op='+';for(int i=0;i<=s.Length;i++){char c=i<s.Length?s[i]:'\0';if(char.IsDigit(c))n=n*10+c-'0';if((!char.IsDigit(c)&&c!=' ')||c=='\0'){if(op=='+')st.Push(n);else if(op=='-')st.Push(-n);else if(op=='*')st.Push(st.Pop()*n);else st.Push(st.Pop()/n);op=c;n=0;}}int r=0;foreach(int x in st)r+=x;return r;}}
